namespace {

constexpr float kFontSize = 16.0f; // at UI scale 1.0
// Material Symbols draws its icons 560 of its 1152-unit line tall: at 1.5x they're about Roboto's cap height.
constexpr float kIconSize = kFontSize * 1.5f;
constexpr int kScreenshotTimeoutFrames = 30;

// Fills whose text darkenTextOnAccent recolors, told apart from the same colors elsewhere (fields, cards) by an alpha
// of 0xfe, which looks the same.
constexpr ImU32 kTabFill = withAlpha(kCard, 0xfe);     // an inactive tab: secondary text
constexpr ImU32 kSelectedFill = withAlpha(kField, 0xfe); // the active tab, a header, a selected row: accent text

// A card's own splitter (channel 0 = its background, 1 = its content), not the draw list's: tables and columns inside
// a card split with their own splitters too, so nothing drawn in a card can collide with it.
ImDrawListSplitter cardSplitter;

float cardRounding() { return ImGui::GetFontSize() * 0.25f; } // 4 px at UI scale 1
// How far a framed collapsing header reaches past the content region, so the card does too.
float cardInset() { return std::floor(ImGui::GetStyle().WindowPadding.x * 0.5f); }
float cardMargin() { return ImGui::GetStyle().WindowPadding.x; } // between a card and the window's sides
float cardGap() { return ImGui::GetFontSize() * 0.5f; }          // added to the item spacing between cards

// Narrows (or with a negative amount, widens back) the region headers and full-width items span, on both sides.
void narrowContent(float amount)
{
    ImGuiWindow* window = ImGui::GetCurrentWindow();
    window->WorkRect.Max.x -= amount;
    window->ContentRegionRect.Max.x -= amount;
    if (amount > 0.0f)
        ImGui::Indent(amount);
    else
        ImGui::Unindent(-amount);
}

} // namespace

float clampUiScale(float scale) { return std::clamp(scale, kMinUiScale, kMaxUiScale); }

void loadFont()
{
    ImGui::GetStyle().FontSizeBase = kFontSize;
    ImFontConfig config;
    config.FontDataOwnedByAtlas = false; // static embedded data
    ImFontAtlas* fonts = ImGui::GetIO().Fonts;
    if (!fonts->AddFontFromMemoryTTF(kRobotoRegularTtf, sizeof(kRobotoRegularTtf), kFontSize, &config)) {
        kast::log::error("Failed to load embedded Roboto font, using ImGui default font");
        fonts->AddFontDefault();
    }
    // Merged into the font above, every codepoint but the three icons excluded (since 1.92 GlyphRanges only limits a
    // legacy preload).
    static constexpr ImWchar kNotIcons[] = {
        1, 0xE033, 0xE035, 0xE036, 0xE038, 0xE046, 0xE048, IM_UNICODE_CODEPOINT_MAX, 0};
    ImFontConfig icons;
    icons.FontDataOwnedByAtlas = false;
    icons.MergeMode = true;
    icons.GlyphExcludeRanges = kNotIcons;
    icons.GlyphOffset.y = kFontSize * 5.0f / 16.0f; // icon centers (10 px above the baseline at 24 px) on Roboto's line
    if (!fonts->AddFontFromMemoryTTF(kMaterialSymbolsTtf, sizeof(kMaterialSymbolsTtf), kIconSize, &icons))
        kast::log::error("Failed to load embedded Material Symbols font: the Play / Pause / Stop icons will not show");
}

void disabledTooltip(const char* reason)
{
    if (reason && ImGui::IsItemHovered(ImGuiHoveredFlags_AllowWhenDisabled))
        ImGui::SetTooltip("%s", reason);
}

namespace {

// The last item as a drop target for an Assets file whose path passes accept.
bool acceptAssetPayload(std::string& path, bool (*accept)(const char* file))
{
    const ImGuiPayload* dragged = ImGui::GetDragDropPayload();
    if (!dragged || !dragged->IsDataType(kAssetPayload) || !accept(static_cast<const char*>(dragged->Data)) ||
        !ImGui::BeginDragDropTarget())
        return false;
    const ImGuiPayload* payload = ImGui::AcceptDragDropPayload(kAssetPayload);
    if (payload)
        path = static_cast<const char*>(payload->Data);
    ImGui::EndDragDropTarget();
    return payload != nullptr;
}

} // namespace

bool acceptModelDrop(std::string& path)
{
    return acceptAssetPayload(path, [](const char* file) { return kast::isModelFile(file); });
}

bool acceptPrefabDrop(std::string& path)
{
    return acceptAssetPayload(path, [](const char* file) {
        return std::filesystem::path(file).extension() == kast::kPrefabExtension;
    });
}

bool acceptGuiPrefabDrop(std::string& path)
{
    return acceptAssetPayload(path, [](const char* file) {
        return std::filesystem::path(file).extension() == kast::kGuiPrefabExtension;
    });
}

void drawPrefabIcon(float x, float y, float height)
{
    ImDrawList* draw = ImGui::GetWindowDrawList();
    const float s = ImGui::GetFontSize() * 0.6f; // icon height
    const float top = y + (height - s) * 0.5f;
    const ImU32 color = ImGui::GetColorU32(ImGuiCol_Button);
    const float w = s * 0.5f, q = s * 0.25f;
    const ImVec2 up{x + w, top}, left{x, top + q}, right{x + s, top + q}, mid{x + w, top + 2.0f * q};
    const ImVec2 bottomLeft{x, top + s - q}, bottomRight{x + s, top + s - q}, bottom{x + w, top + s};
    draw->AddQuadFilled(up, right, mid, left, color);
    const float line = std::max(1.0f, s * 0.1f);
    const ImVec2 outline[] = {left, bottomLeft, bottom, bottomRight, right};
    draw->AddPolyline(outline, 5, color, ImDrawFlags_None, line);
    draw->AddLine(mid, bottom, color, line);
}

void markOverride(float top, float bottom)
{
    const float x = ImGui::GetWindowPos().x + 1.0f;
    ImGui::GetWindowDrawList()->PushClipRectFullScreen();
    ImGui::GetWindowDrawList()->AddRectFilled({x, top}, {x + 4.0f, bottom}, kHighlight);
    ImGui::GetWindowDrawList()->PopClipRect();
}

void beginCard()
{
    IM_ASSERT(cardSplitter._Count <= 1 && "cards do not nest");
    cardSplitter.Split(ImGui::GetWindowDrawList(), 2);
    cardSplitter.SetCurrentChannel(ImGui::GetWindowDrawList(), 1);
    ImGui::PushItemWidth(ImGui::CalcItemWidth() - 2.0f * cardMargin()); // labels stay clear of the card's right side
    narrowContent(cardMargin());
    ImGui::BeginGroup();
}

void endCard()
{
    ImGui::EndGroup();
    ImDrawList* drawList = ImGui::GetWindowDrawList();
    const float inset = cardInset();
    const float left = ImGui::GetCursorScreenPos().x;
    const ImVec2 min(left - inset, ImGui::GetItemRectMin().y);
    const ImVec2 max(left + ImGui::GetContentRegionAvail().x + inset, ImGui::GetItemRectMax().y + inset);
    cardSplitter.SetCurrentChannel(drawList, 0);
    drawList->AddRectFilled(min, max, kCard, cardRounding());
    cardSplitter.SetCurrentChannel(drawList, 1); // the border over the content, so the header does not cover it
    drawList->AddRect(min, max, ImGui::GetColorU32(ImGuiCol_Border), cardRounding());
    cardSplitter.Merge(drawList);
    narrowContent(-cardMargin());
    ImGui::PopItemWidth();
    ImGui::Dummy(ImVec2(0.0f, inset + cardGap())); // the card's bottom padding and the gap below it
}

bool cardHeader(const char* label, bool* open, ImGuiTreeNodeFlags flags)
{
    ImGui::PushStyleVar(ImGuiStyleVar_FrameRounding, cardRounding());
    const bool expanded = ImGui::CollapsingHeader(label, open, flags);
    ImGui::PopStyleVar();
    return expanded;
}

void applyTheme()
{
    ImGui::StyleColorsDark(); // the base for anything not set below
    ImVec4* c = ImGui::GetStyle().Colors;
    c[ImGuiCol_Text] = toVec4(kText);
    c[ImGuiCol_TextDisabled] = toVec4(kTextSecondary);
    // The title bars are the dock nodes' tab bars.
    for (ImGuiCol col : {ImGuiCol_WindowBg, ImGuiCol_MenuBarBg, ImGuiCol_ScrollbarBg, ImGuiCol_DockingEmptyBg,
                         ImGuiCol_TitleBg, ImGuiCol_TitleBgActive, ImGuiCol_TitleBgCollapsed})
        c[col] = toVec4(kBackground);
    for (ImGuiCol col : {ImGuiCol_PopupBg, ImGuiCol_TableHeaderBg})
        c[col] = toVec4(kCard);
    for (ImGuiCol col : {ImGuiCol_FrameBg, ImGuiCol_Border, ImGuiCol_Separator, ImGuiCol_ScrollbarGrab,
                         ImGuiCol_TableBorderStrong, ImGuiCol_TableBorderLight})
        c[col] = toVec4(kField);
    for (ImGuiCol col : {ImGuiCol_FrameBgHovered, ImGuiCol_FrameBgActive, ImGuiCol_ScrollbarGrabHovered,
                         ImGuiCol_ScrollbarGrabActive, ImGuiCol_TextSelectedBg})
        c[col] = toVec4(kFieldHighlight);
    for (ImGuiCol col : {ImGuiCol_Button, ImGuiCol_CheckMark, ImGuiCol_SliderGrab, ImGuiCol_PlotLines,
                         ImGuiCol_PlotHistogram})
        c[col] = toVec4(kAccent);
    for (ImGuiCol col : {ImGuiCol_ButtonHovered, ImGuiCol_SeparatorHovered, ImGuiCol_ResizeGripHovered,
                         ImGuiCol_SliderGrabActive, ImGuiCol_PlotLinesHovered, ImGuiCol_PlotHistogramHovered,
                         ImGuiCol_NavCursor, ImGuiCol_DragDropTarget, ImGuiCol_TextLink})
        c[col] = toVec4(kHighlight);
    for (ImGuiCol col : {ImGuiCol_ButtonActive, ImGuiCol_SeparatorActive, ImGuiCol_ResizeGripActive})
        c[col] = toVec4(kPressed);
    // Tabs and headers are grey, their text recolored by darkenTextOnAccent.
    for (ImGuiCol col : {ImGuiCol_Tab, ImGuiCol_TabDimmed})
        c[col] = toVec4(kTabFill);
    for (ImGuiCol col : {ImGuiCol_TabSelected, ImGuiCol_TabDimmedSelected, ImGuiCol_Header, ImGuiCol_HeaderActive})
        c[col] = toVec4(kSelectedFill);
    for (ImGuiCol col : {ImGuiCol_TabHovered, ImGuiCol_HeaderHovered})
        c[col] = toVec4(kRowHover);
    for (ImGuiCol col : {ImGuiCol_TabSelectedOverline, ImGuiCol_TabDimmedSelectedOverline})
        c[col] = toVec4(withAlpha(kBackground, 0));
    c[ImGuiCol_ResizeGrip] = toVec4(withAlpha(kAccent, 0x40));
    c[ImGuiCol_DockingPreview] = toVec4(withAlpha(kAccent, 0xb3));
}

void darkenTextOnAccent(ImDrawData* drawData)
{
    constexpr ImU32 kRgb = ~IM_COL32_A_MASK;
    const ImU32 textRgb = ImGui::GetColorU32(ImGuiCol_Text) & kRgb;
    const auto isText = [&](const ImDrawVert& v) { return (v.col & kRgb) == textRgb; };
    // The text color over a fill of v's color, 0 if it keeps its own. A marked fill's anti-aliased fringe has alpha 0.
    const auto textOn = [](const ImDrawVert& v) -> ImU32 {
        const ImU32 rgb = v.col & kRgb, alpha = v.col & IM_COL32_A_MASK;
        if (rgb == (kAccent & kRgb) || rgb == (kHighlight & kRgb) || rgb == (kPressed & kRgb))
            return IM_COL32_BLACK;
        const bool marked = alpha == (kSelectedFill & IM_COL32_A_MASK) || alpha == 0;
        if (marked && rgb == (kSelectedFill & kRgb))
            return kAccent;
        if (marked && rgb == (kTabFill & kRgb))
            return kTextSecondary;
        return 0;
    };
    struct Fill {
        ImRect rect;
        ImU32 text;
    };
    const float minFill = ImGui::GetFontSize() * 0.5f;
    std::vector<ImU32> recolor;
    std::vector<Fill> fills;
    for (ImDrawList* list : drawData->CmdLists) {
        // Vertices are in submission order: a widget's fill comes before the text drawn on it.
        // ponytail: every text vertex is tested against every fill so far, fine for a few dozen fills per window.
        recolor.assign(list->VtxBuffer.Size, 0);
        fills.clear();
        ImU32 inFill = 0; // the current run of fill vertices' text color
        for (int i = 0; i < list->VtxBuffer.Size; ++i) {
            const ImDrawVert& v = list->VtxBuffer[i];
            const ImU32 text = textOn(v);
            if (text != inFill) {
                // Lines (a tab bar's underline) and marks too small to hold text are not fills.
                if (inFill && (fills.back().rect.GetWidth() < minFill || fills.back().rect.GetHeight() < minFill))
                    fills.pop_back();
                if (text)
                    fills.push_back({ImRect(v.pos, v.pos), text});
                inFill = text;
            }
            if (text) {
                fills.back().rect.Add(v.pos);
                continue;
            }
            if (!isText(v))
                continue;
            // The last fill under it: a tab drawn over its tab bar's underline.
            const auto under =
                std::find_if(fills.rbegin(), fills.rend(), [&](const Fill& f) { return f.rect.Contains(v.pos); });
            if (under != fills.rend())
                recolor[i] = under->text;
        }

        // Whole triangles, so a glyph whose descender hangs below the fill changes as one. Only those sampling the
        // font atlas: images (the viewports, thumbnails) carry a plain texture id and keep their white tint.
        for (const ImDrawCmd& cmd : list->CmdBuffer) {
            if (cmd.UserCallback || !cmd.TexRef._TexData)
                continue;
            for (unsigned int i = 0; i + 2 < cmd.ElemCount; i += 3) {
                const ImDrawIdx* tri = &list->IdxBuffer[cmd.IdxOffset + i];
                const unsigned int a = cmd.VtxOffset + tri[0], b = cmd.VtxOffset + tri[1], c = cmd.VtxOffset + tri[2];
                const ImU32 text = recolor[a] ? recolor[a] : recolor[b] ? recolor[b] : recolor[c];
                if (!text)
                    continue;
                for (unsigned int index : {a, b, c}) {
                    ImDrawVert& v = list->VtxBuffer[index];
                    if (isText(v))
                        v.col = (v.col & IM_COL32_A_MASK) | (text & kRgb);
                }
            }
        }
    }
}

void UiScale::init(SDL_Window* window)
{
    window_ = window;
    base_ = ImGui::GetStyle();
    apply();
}

void UiScale::onEvent(const SDL_Event& event)
{
    if (event.type == SDL_EVENT_WINDOW_DISPLAY_SCALE_CHANGED && !forced_)
        apply();
}

void UiScale::apply()
{
    const float scale = forced_ ? *forced_ : clampUiScale(displayScale());
    if (scale == current_) // SDL can report an unchanged scale, e.g. once at startup
        return;
    current_ = scale;
    ImGuiStyle& style = ImGui::GetStyle();
    style = base_;
    style.ScaleAllSizes(scale);
    style.FontScaleDpi = scale;
    kast::log::info(std::format("UI scale {:.2f} ({})", scale, forced_ ? "--ui-scale" : "display"));
}

float UiScale::displayScale() const
{
    const float scale = SDL_GetWindowDisplayScale(window_);
    if (scale > 0.0f)
        return scale;
    kast::log::error(std::format("SDL_GetWindowDisplayScale failed: {}", SDL_GetError()));
    return 1.0f;
}

void FrameLimit::endFrame()
{
    ++frame_;
    if (!logText_.empty()) {
        const std::vector<std::string>& lines = kast::log::lines();
        for (; logSeen_ < lines.size(); ++logSeen_) {
            if (lines[logSeen_].find(logText_) != std::string::npos) {
                frames_ = std::min(frames_, frame_ + logDelay_);
                logText_.clear();
                break;
            }
        }
    }
    if (frames_ == 0 || frame_ < frames_)
        return;
    if (screenshot_.empty()) {
        if (frame_ == frames_)
            kast::requestQuit();
    } else if (!requested_) {
        bgfx::requestScreenShot(BGFX_INVALID_HANDLE, screenshot_.c_str());
        requested_ = true;
    } else if (frame_ == frames_ + kScreenshotTimeoutFrames) {
        kast::log::error("Screenshot timed out");
        failed_ = true;
        kast::requestQuit();
    }
}

void FrameLimit::onScreenshotSaved(bool saved)
{
    saved_ = saved;
    kast::requestQuit();
}

void FpsLog::endFrame(uint64_t frameStart, const kast::RenderStats* scene, int hizLatency)
{
    const uint64_t now = SDL_GetPerformanceCounter();
    const auto frequency = static_cast<double>(SDL_GetPerformanceFrequency());
    cpuSeconds_ += static_cast<double>(now - frameStart) / frequency;
    ++frames_;
    if (windowStart_ == 0)
        windowStart_ = now;
    const double elapsed = static_cast<double>(now - windowStart_) / frequency;
    if (elapsed < 1.0)
        return;
    const bgfx::Stats* stats = bgfx::getStats();
    const double gpuMs = 1000.0 * static_cast<double>(stats->gpuTimeEnd - stats->gpuTimeBegin) /
                         static_cast<double>(stats->gpuTimerFreq);
    std::string line = std::format("FPS {:.1f}, CPU {:.2f} ms/frame, GPU {:.2f} ms/frame, {} draw calls", frames_ / elapsed,
                                   1000.0 * cpuSeconds_ / frames_, gpuMs, stats->numDraw);
    if (scene)
        line += std::format("; Scene view: {}, Hi-Z latency {} frames", kast::renderStatsText(*scene), hizLatency);
    kast::log::info(line);
    windowStart_ = now;
    frames_ = 0;
    cpuSeconds_ = 0.0;
}
